# School pages: "How to get into investment banking from <school>". Facts about each school's clubs and
# programs come from the sources listed on each page (checked 2026-11-10). Build with: python3 guides/_src/extra.py
S = lambda pairs: "Sources: " + " · ".join(f'<a href="{u}" rel="nofollow">{n}</a>' for n, u in pairs)

def timeline(school):
    return [("h2", f"Your timeline at {school}"),
        ("table", ["When", "What to do"], [
            ["Freshman fall", "Join 1–2 finance clubs. Keep your GPA high (many programs want 3.5+, some 3.7+)."],
            ["Freshman spring–summer", "Learn accounting and valuation basics. Start 1–2 alumni coffee chats a month. Apply to early-insight programs."],
            ["Sophomore fall–spring", "Apply to your school's selective IB program. Main window for junior-summer IB internships: applications, interviews and Superdays (recent cycles opened as early as sophomore fall)."],
            ["Junior summer", "The internship that usually turns into your full-time offer."]]),
        ("p", "Recruiting runs about 1.5–2 years ahead of the internship, so the work starts earlier than most students expect. See the full <a href=\"/guides/investment-banking-recruiting-timeline/\">recruiting timeline</a>.")]

def standout(extra):
    return [("h2", "How to stand out"),
        ("card", "What actually moves the needle", extra + [
            "Nail the technicals: the three statements, enterprise value, DCF and a paper LBO. Practice them out loud.",
            "Network early with alumni from your school at banks. A warm intro often decides who gets the first interview.",
            "Have a tight 60-second story for \"walk me through your resume\" and \"why investment banking.\""])]

CTA = ("cta", "Practice real IB interview questions in 5-minute levels, free.", "/", "Start training on M&A Prep")

